def calculate_system_metrics(task_set):
    E_s_sum = 0
    S_s_sum = 0
    E_sum = 0
    u_s_max = 0

    for task in task_set:
        E_sum += task.e
        if task.is_suspending:
            E_s_sum += task.e
            S_s_sum += task.s
            u_s_max = max(u_s_max, task.u)

    return {"E_s_sum": E_s_sum, "S_s_sum": S_s_sum, "E_sum": E_sum, "u_s_max": u_s_max}

class TaskPSAC(Task):
    def __init__(self, e, s, p, is_suspending=True):
        super().__init__(e, s, p, is_suspending)
        self.c_i = 0 # Amount of suspension treated as computation

    @property
    def xi_prime(self):
        if not self.is_suspending:
            return 0
        effective_s = self.s - self.c_i
        return effective_s / (self.e + self.s) if (self.e + self.s) > 0 else 0

def calculate_xi_max_prime(task_set_psac):
    xi_max_prime = 0
    for task in task_set_psac:
        if task.is_suspending:
            xi_max_prime = max(xi_max_prime, task.xi_prime)
    return xi_max_prime
